        seen = set()
        for r in range(1, h):
            for c in range(w):
                if grid[r][c] and (r, c) not in seen:
                    col = grid[r][c]
                    stack = [(r, c)]; seen.add((r, c)); cells=[]
                    while stack:
                        y,x=stack.pop(); cells.append((y,x))
                        for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                            if 1 <= yy < h and 0 <= xx < w and grid[yy][xx] == col and (yy,xx) not in seen:
                                seen.add((yy,xx)); stack.append((yy,xx))
                    objs.append(cells)
        objs.sort(key=lambda cells: min(r for r,c in cells))
        out=[[0]*w for _ in range(h)]; out[0]=grid[0][:]
        nextrow=1
        for cells in objs:
            top=min(r for r,c in cells); bottom=max(r for r,c in cells)
            left=min(c for r,c in cells)
            height=bottom-top+1
            for r,c in cells: out[nextrow+r-top][left+c-left]=grid[r][c]
