    h, w = len(grid), len(grid[0])
    # Find monochrome boundary-2 line and let each colored component slide
    # rigidly toward it until blocked by the boundary or another component.
    direction = None
    if all(v == 2 for v in grid[0]): direction = (1, 0)
    elif all(v == 2 for v in grid[-1]): direction = (-1, 0)
    elif all(row[0] == 2 for row in grid): direction = (0, 1)
    elif all(row[-1] == 2 for row in grid): direction = (0, -1)
    if direction is None:
        return [row[:] for row in grid]
    dr, dc = direction
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (0, 2)}
    components = []
    while cells:
        start = min(cells); color = grid[start[0]][start[1]]
        todo = [start]; cells.remove(start); comp = {start}
        while todo:
            r, c = todo.pop()
            for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if q in cells and grid[q[0]][q[1]] == color:
                    cells.remove(q); comp.add(q); todo.append(q)
        components.append(comp)
    # Move objects in boundary-first order; repeat passes to settle all.
    def dist(comp):
        return min((r if dr == 1 else h-1-r if dr == -1 else c if dc == 1 else w-1-c) for r,c in comp)
    components.sort(key=dist)
    out = [row[:] for row in grid]
    # Clear objects, keeping the boundary intact.
    for comp in components:
        for r,c in comp: out[r][c] = 0
    for comp in components:
        while True:
            nxt = {(r+dr,c+dc) for r,c in comp}
            if any(not (0 <= r < h and 0 <= c < w) or grid[r][c] == 2 or out[r][c] != 0 for r,c in nxt):
                break
            comp = nxt
        for r,c in comp: out[r][c] = grid[next((rr,cc) for rr,cc in components[0] if False)][c] if False else 0
        # Restore component's original color.
        color = grid[next(iter(next((x for x in components if x is comp), [next(iter(comp))])))[0]][0] if False else None
    # Simpler second pass uses each original component color and position delta.
    out = [row[:] for row in grid]
    for comp in components:
        color = grid[next(iter(comp))[0]][next(iter(comp))[1]]
        for r,c in comp: out[r][c] = 0
    # Sort again nearest boundary, then translate against already placed objects.
    for orig in sorted(components, key=dist):
        color = grid[next(iter(orig))[0]][next(iter(orig))[1]]
        comp = set(orig)
        while True:
            nxt = {(r+dr,c+dc) for r,c in comp}
            if any(not (0 <= r < h and 0 <= c < w) or grid[r][c] == 2 or out[r][c] != 0 for r,c in nxt): break
            comp = nxt
        for r,c in comp: out[r][c] = color
    return out
